fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    // Since input length > 0, safe to unwrap elements by index

    // If length is 1, return a clone of the input (identical array)
    if n == 1 {
        return a.clone();
    }

    // Create a new vector with the same elements as `a`
    // We'll swap the first and last elements in the new vector
    let mut result = a.clone();

    // Swap first and last elements
    result[0] = a[n - 1];
    result[n - 1] = a[0];

    result
}